mapper.select:
SELECT * FROM price_log

    AND ingredient_id = #{ingredientId}
    AND category_name IN (SELECT name FROM ingredient_category WHERE id=#{categoryId})
    AND supplier_name IN (SELECT name FROM supplier WHERE id=#{supplierId})
    AND change_type = #{changeType}
    AND created_at >= #{start}
    AND created_at <= #{end}

ORDER BY created_at DESC
